from __future__ import absolute_import
import os
from ftplib import FTP

from robot.api import logger


class FtpFileUploader(object):
    """

    """

    def __init__(self):
        self._ftp = FTP()

    def connect_ftp(self, ip, username, password):
        """
        This KW establishes connection to given
        host and login with given credentials.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Establish connection to given host with given credentials.
        | This method is setup for "upload_file_via_ftp" method

        **Input Parameters:**

        +--------------------+--------+---------------+
        | Input Parameters   | Man.   | Description   |
        +====================+========+===============+
        | ip                 | Yes    | target ip     |
        +--------------------+--------+---------------+
        | username           | Yes    | username      |
        +--------------------+--------+---------------+
        | password           | Yes    | password      |
        +--------------------+--------+---------------+

        **Example:**

        .. code-block:: robotframework

           Connect ftp  ip=xxx.xxx.xxx.xxx  user=someuser  password=somepasswd
        """
        self._ftp.connect(ip)
        self._ftp.login(username, password)

    def upload_file_via_ftp(self, source_path, destination_path):
        """
        Keyword for uploading file via ftp, requires connection
        established through "connect ftp" keyword.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** damian.skrzypczak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Upload file located in source_path to host'
        | destination_path via FTP protocol.
        | Performing method connect_ftp() first is mandatory.

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | source_path        | Yes    | Path to file which is going           |
        |                    |        | to be uploaded                        |
        +--------------------+--------+---------------------------------------+
        | destination_path   | Yes    | Path on host where file is            |
        |                    |        | going to be copied to                 |
        +--------------------+--------+---------------------------------------+


        **Example:**

        .. code-block:: robotframework

           upload_file_via_ftp  source_path=/home/ute/file1.txt
           ...  destination_path=/flash/config

        """
        try:
            source = open(source_path, 'rb')
            path_split = source_path.split('/')
            filename = path_split[len(path_split) - 1]
            complete_path = os.path.join(destination_path, filename)
            cmd = 'STOR ' + complete_path

            self._ftp.storbinary(cmd, source)
            self._ftp.close()

        except IOError as e:
            logger.warn("Cannot open file because of IOError.")
            raise e

        except Exception as e:
            logger.warn("Unexpected error. {}".format(e))
            raise e
